export const ActionsRef: Story = {
  name: 'Actions Ref',
  render: () => render(examples['Actions Ref']),
  parameters: {
    docs: {
      source: {
        language: 'tsx',
        code: "import { Button, Drawer, IconButton, Textarea, Typography } from 'ljkui';\n\nconst args = {};\nconst actionsRef = React.useRef<Drawer.Actions>(null!);\nconst [isSubmitting, setIsSubmitting] = React.useState(false);\n\nconst handleSubmit = async () => {\n  setIsSubmitting(true);\n  // Simulate async operation\n  await new Promise((resolve) => setTimeout(resolve, 1500));\n  setIsSubmitting(false);\n  // Close drawer programmatically after operation completes\n  actionsRef.current?.close();\n};\n\nreturn (\n  <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)', alignItems: 'center' }}>\n    <Typography.Text>\n      Use <Typography.Code>actionsRef</Typography.Code> to close the drawer programmatically after an async\n      operation.\n    </Typography.Text>\n\n    <Drawer.Root actionsRef={actionsRef}>\n      <Drawer.Trigger>\n        <Button variant=\"classic\">Submit Feedback</Button>\n      </Drawer.Trigger>\n      <Drawer.Content {...args}>\n        <Drawer.Header>\n          <Drawer.Title>Submit Feedback</Drawer.Title>\n          <Drawer.Close>\n            <IconButton size=\"1\" color=\"gray\" variant=\"ghost\" disabled={isSubmitting}>\n              <X size={16} />\n            </IconButton>\n          </Drawer.Close>\n        </Drawer.Header>\n        <Drawer.Body>\n          <Typography.Text render={<p />} size=\"2\" style={{ marginBottom: 'var(--space-4)' }}>\n            The drawer will close automatically when the form submission completes.\n          </Typography.Text>\n\n          <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-3)' }}>\n            <label>\n              <Typography.Text render={<div />} size=\"2\" style={{ marginBottom: 'var(--space-1)' }} weight=\"bold\">\n                Feedback\n              </Typography.Text>\n              <Textarea placeholder=\"Enter your feedback...\" style={{ minHeight: 120 }} />\n            </label>\n          </div>\n\n          <div\n            style={{\n              display: 'flex',\n              gap: 'var(--space-3)',\n              marginTop: 'var(--space-4)',\n              justifyContent: 'flex-end',\n            }}\n          >\n            <Drawer.Close>\n              <Button variant=\"soft\" color=\"gray\" disabled={isSubmitting}>\n                Cancel\n              </Button>\n            </Drawer.Close>\n            <Button variant=\"classic\" onClick={handleSubmit} disabled={isSubmitting}>\n              {isSubmitting ? 'Submitting...' : 'Submit'}\n            </Button>\n          </div>\n        </Drawer.Body>\n      </Drawer.Content>\n    </Drawer.Root>\n  </div>\n);",
      },
    },
  },
};

