export const OpenChangeCallbacks: Story = {
  name: 'Open Change Callbacks',
  render: () => render(examples['Open Change Callbacks']),
  parameters: {
    docs: {
      source: {
        language: 'tsx',
        code: "import { Button, Drawer, IconButton, Typography } from 'ljkui';\n\nconst args = {};\nconst [logs, setLogs] = React.useState<string[]>([]);\n\nconst addLog = (message: string) => {\n  const time = new Date().toLocaleTimeString('en-US', {\n    hour12: false,\n    hour: '2-digit',\n    minute: '2-digit',\n    second: '2-digit',\n    fractionalSecondDigits: 3,\n  });\n  setLogs((prev) => [`[${time}] ${message}`, ...prev].slice(0, 10));\n};\n\nreturn (\n  <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-4)', alignItems: 'center' }}>\n    <Typography.Text>\n      Compare <Typography.Code>onOpenChange</Typography.Code> (fires immediately) vs{' '}\n      <Typography.Code>onOpenChangeComplete</Typography.Code> (fires after animations).\n    </Typography.Text>\n\n    <Drawer.Root\n      onOpenChange={(open) => addLog(`onOpenChange: ${open ? 'opening' : 'closing'}`)}\n      onOpenChangeComplete={(open) => addLog(`onOpenChangeComplete: ${open ? 'opened' : 'closed'}`)}\n    >\n      <Drawer.Trigger>\n        <Button variant=\"classic\">Open Drawer</Button>\n      </Drawer.Trigger>\n      <Drawer.Content {...args}>\n        <Drawer.Header>\n          <Drawer.Title>Callback Demo</Drawer.Title>\n          <Drawer.Close>\n            <IconButton size=\"1\" color=\"gray\" variant=\"ghost\">\n              <X size={16} />\n            </IconButton>\n          </Drawer.Close>\n        </Drawer.Header>\n        <Drawer.Body>\n          <Typography.Text render={<p />} size=\"2\">\n            Watch the event log below to see callback timing. Notice how{' '}\n            <Typography.Code>onOpenChangeComplete</Typography.Code> fires after the slide animation completes.\n          </Typography.Text>\n          <div\n            style={{\n              display: 'flex',\n              gap: 'var(--space-3)',\n              marginTop: 'var(--space-4)',\n              justifyContent: 'flex-end',\n            }}\n          >\n            <Drawer.Close>\n              <Button variant=\"soft\" color=\"gray\">\n                Cancel\n              </Button>\n            </Drawer.Close>\n            <Drawer.Close>\n              <Button variant=\"classic\">Done</Button>\n            </Drawer.Close>\n          </div>\n        </Drawer.Body>\n      </Drawer.Content>\n    </Drawer.Root>\n\n    <div\n      style={{\n        padding: 'var(--space-3)',\n        background: 'var(--gray-alpha-100)',\n        borderRadius: 'var(--radius-2)',\n        fontFamily: 'monospace',\n        fontSize: 'var(--font-size-1)',\n        minHeight: 150,\n        width: 400,\n      }}\n    >\n      <Typography.Text size=\"1\" weight=\"medium\" style={{ marginBottom: 8, display: 'block' }}>\n        Event Log:\n      </Typography.Text>\n      {logs.length === 0 ? (\n        <Typography.Text size=\"1\" color=\"gray\">\n          Open/close the drawer to see events...\n        </Typography.Text>\n      ) : (\n        logs.map((log, i) => (\n          <div key={i} style={{ color: log.includes('Complete') ? 'var(--accent-900)' : 'var(--gray-900)' }}>\n            {log}\n          </div>\n        ))\n      )}\n    </div>\n  </div>\n);",
      },
    },
  },
};

