export const DeeplyNestedDrawers: Story = {
  name: 'Deeply Nested Drawers',
  render: () => render(examples['Deeply Nested Drawers']),
  parameters: {
    docs: {
      source: {
        language: 'tsx',
        code: 'import { Button, Drawer, IconButton, Typography } from \'ljkui\';\n\nconst args = {};\nconst level1Ref = React.useRef<Drawer.Actions>(null!);\nconst level2Ref = React.useRef<Drawer.Actions>(null!);\nconst level3Ref = React.useRef<Drawer.Actions>(null!);\n\nconst closeAll = () => {\n  // Close from innermost to outermost for smooth animation\n  level3Ref.current?.close();\n  level2Ref.current?.close();\n  level1Ref.current?.close();\n};\n\nreturn (\n  <div style={{ display: \'flex\', flexDirection: \'column\', gap: \'var(--space-4)\', alignItems: \'center\' }}>\n    <Typography.Text style={{ maxWidth: 500, textAlign: \'center\' }}>\n      Drawers can be nested multiple levels deep. Each level scales and shifts the parent drawers. Use{\' \'}\n      <Typography.Code>actionsRef</Typography.Code> to close all drawers at once.\n    </Typography.Text>\n\n    <Drawer.Root actionsRef={level1Ref}>\n      <Drawer.Trigger>\n        <Button variant="classic">Open Level 1</Button>\n      </Drawer.Trigger>\n      <Drawer.Content {...args}>\n        <Drawer.Header>\n          <Drawer.Title>Level 1</Drawer.Title>\n          <Drawer.Close>\n            <IconButton size="1" color="gray" variant="ghost">\n              <X size={16} />\n            </IconButton>\n          </Drawer.Close>\n        </Drawer.Header>\n        <Drawer.Body>\n          <Typography.Text render={<p />} size="2" style={{ marginBottom: \'var(--space-4)\' }}>\n            First level drawer. Open another to see the stacking effect.\n          </Typography.Text>\n\n          <div\n            style={{\n              display: \'flex\',\n              gap: \'var(--space-3)\',\n              justifyContent: \'flex-end\',\n            }}\n          >\n            <Drawer.Root actionsRef={level2Ref}>\n              <Drawer.Trigger>\n                <Button variant="soft">Open Level 2</Button>\n              </Drawer.Trigger>\n              <Drawer.Content {...args} style={{ maxWidth: 350 }}>\n                <Drawer.Header>\n                  <Drawer.Title>Level 2</Drawer.Title>\n                  <Drawer.Close>\n                    <IconButton size="1" color="gray" variant="ghost">\n                      <X size={16} />\n                    </IconButton>\n                  </Drawer.Close>\n                </Drawer.Header>\n                <Drawer.Body>\n                  <Typography.Text render={<p />} size="2" style={{ marginBottom: \'var(--space-4)\' }}>\n                    Second level drawer. One more to go!\n                  </Typography.Text>\n\n                  <div\n                    style={{\n                      display: \'flex\',\n                      gap: \'var(--space-3)\',\n                      justifyContent: \'flex-end\',\n                    }}\n                  >\n                    <Drawer.Root actionsRef={level3Ref}>\n                      <Drawer.Trigger>\n                        <Button variant="soft">Open Level 3</Button>\n                      </Drawer.Trigger>\n                      <Drawer.Content {...args} style={{ maxWidth: 320 }}>\n                        <Drawer.Header>\n                          <Drawer.Title>Level 3</Drawer.Title>\n                          <Drawer.Close>\n                            <IconButton size="1" color="gray" variant="ghost">\n                              <X size={16} />\n                            </IconButton>\n                          </Drawer.Close>\n                        </Drawer.Header>\n                        <Drawer.Body>\n                          <Typography.Text render={<p />} size="2" style={{ marginBottom: \'var(--space-4)\' }}>\n                            Third level - the deepest drawer. Notice how all parent drawers have scaled and shifted.\n                          </Typography.Text>\n\n                          <div\n                            style={{\n                              display: \'flex\',\n                              gap: \'var(--space-3)\',\n                              justifyContent: \'flex-end\',\n                            }}\n                          >\n                            <Button variant="classic" onClick={closeAll}>\n                              Close All\n                            </Button>\n                          </div>\n                        </Drawer.Body>\n                      </Drawer.Content>\n                    </Drawer.Root>\n                    <Drawer.Close>\n                      <Button variant="soft" color="gray">\n                        Close\n                      </Button>\n                    </Drawer.Close>\n                  </div>\n                </Drawer.Body>\n              </Drawer.Content>\n            </Drawer.Root>\n            <Drawer.Close>\n              <Button variant="soft" color="gray">\n                Close\n              </Button>\n            </Drawer.Close>\n          </div>\n        </Drawer.Body>\n      </Drawer.Content>\n    </Drawer.Root>\n  </div>\n);',
      },
    },
  },
};

